package main

const schemaSQL = `
create table if not exists topics (
	id bigserial primary key,
	title text not null,
	chapter text not null default '',
	description text not null default '',
	difficulty int not null default 1,
	semester int not null default 1,
	sort_order int not null default 0,
	created_at timestamptz not null default now()
);

create table if not exists users (
	id bigserial primary key,
	username text not null unique,
	display_name text not null,
	password_hash text not null,
	is_admin boolean not null default false,
	created_at timestamptz not null default now()
);

create table if not exists theory_items (
	id bigserial primary key,
	topic_id bigint not null references topics(id) on delete cascade,
	type text not null check (type in ('definition', 'theorem', 'criterion', 'property', 'example', 'proof')),
	title text not null,
	statement text not null default '',
	explanation text not null default '',
	proof_outline text not null default '',
	proof_full text not null default '',
	source_page int,
	created_at timestamptz not null default now()
);

create table if not exists cards (
	id bigserial primary key,
	topic_id bigint not null references topics(id) on delete cascade,
	theory_item_id bigint references theory_items(id) on delete set null,
	type text not null check (type in ('definition', 'theorem', 'criterion', 'formula', 'proof_outline')),
	front text not null,
	back text not null,
	hint text not null default '',
	difficulty int not null default 1,
	created_at timestamptz not null default now()
);

create table if not exists questions (
	id bigserial primary key,
	topic_id bigint not null references topics(id) on delete cascade,
	theory_item_id bigint references theory_items(id) on delete set null,
	type text not null check (type in ('prove', 'derive', 'explain', 'example', 'true_false', 'formulate', 'oral')),
	exam_kind text not null default 'theory' check (exam_kind in ('theory', 'ikr', 'tkr')),
	text text not null,
	expected_answer text not null default '',
	short_answer text not null default '',
	difficulty int not null default 1,
	tags text[] not null default '{}',
	source text not null default 'legacy',
	created_at timestamptz not null default now()
);

create table if not exists proof_choice_games (
	id bigserial primary key,
	theory_item_id bigint not null references theory_items(id) on delete cascade,
	question text not null,
	correct_outline text not null,
	wrong_outline_1 text not null,
	wrong_outline_2 text not null,
	wrong_outline_3 text not null,
	explanation text not null default '',
	source text not null default 'legacy',
	created_at timestamptz not null default now()
);

create table if not exists attempts (
	id bigserial primary key,
	demo_student_id bigint not null default 1,
	target_type text not null check (target_type in ('card', 'question', 'proof_game')),
	target_id bigint not null,
	mode text not null check (mode in ('cards', 'formulations', 'proof_game', 'oral', 'variant')),
	grade text not null check (grade in ('bad', 'almost', 'good', 'perfect')),
	notes text not null default '',
	student_answer text not null default '',
	feedback text not null default '',
	points int not null default 0,
	created_at timestamptz not null default now()
);

create table if not exists sessions (
	token_hash text primary key,
	user_id bigint not null references users(id) on delete cascade,
	expires_at timestamptz not null,
	created_at timestamptz not null default now()
);

alter table users add column if not exists is_admin boolean not null default false;

insert into users (id, username, display_name, password_hash)
values (1, 'legacy_demo', 'Демо-участник', '')
on conflict (id) do nothing;

insert into users (id, username, display_name, password_hash)
select distinct a.demo_student_id, 'legacy_' || a.demo_student_id, 'Старый профиль ' || a.demo_student_id, ''
from attempts a
where a.demo_student_id <> 1
on conflict (id) do nothing;

select setval(pg_get_serial_sequence('users', 'id'), greatest((select coalesce(max(id), 1) from users), 1), true);

do $$
begin
	if not exists (select 1 from pg_constraint where conname = 'attempts_demo_student_id_fkey') then
		alter table attempts
			add constraint attempts_demo_student_id_fkey
			foreign key (demo_student_id) references users(id) on delete cascade;
	end if;
end;
$$;

create index if not exists idx_theory_items_topic_id on theory_items(topic_id);
create index if not exists idx_cards_topic_id on cards(topic_id);
create index if not exists idx_questions_topic_id on questions(topic_id);
create index if not exists idx_attempts_demo_student on attempts(demo_student_id, created_at desc);

create table if not exists exam_blueprints (
	id bigserial primary key,
	code text not null unique,
	title text not null,
	description text not null default '',
	exam_kind text not null check (exam_kind in ('theory', 'ikr', 'tkr')),
	question_count int not null default 6
);

alter table questions add column if not exists exam_kind text not null default 'theory';
alter table questions add column if not exists source text not null default 'legacy';
alter table proof_choice_games add column if not exists source text not null default 'legacy';
alter table topics add column if not exists semester int not null default 1;
alter table topics add column if not exists sort_order int not null default 0;
alter table attempts add column if not exists student_answer text not null default '';
alter table attempts add column if not exists feedback text not null default '';
alter table attempts add column if not exists points int not null default 0;
alter table questions drop constraint if exists questions_exam_kind_check;
alter table questions add constraint questions_exam_kind_check check (exam_kind in ('theory', 'ikr', 'tkr'));

create unique index if not exists uniq_topics_title on topics(title);
create unique index if not exists uniq_theory_items_title on theory_items(title);
create unique index if not exists uniq_cards_front on cards(front);
create unique index if not exists uniq_questions_text on questions(text);
create unique index if not exists uniq_proof_choice_question on proof_choice_games(question);
update topics set semester = case when chapter in ('Ф2П', 'КРИ-1', 'КРИ-2', 'Векторный анализ', 'Экстремумы', 'Поверхностные интегралы') then 2 else 1 end;
update topics set sort_order = id where sort_order = 0;
`

